#![allow(clippy::many_single_char_names)]

use crate::Real;
use crate::traits::{Compare, Element, NormedDivisionAlgebra};
use core::ops::{Add, AddAssign, Div, Mul, MulAssign, Neg, Sub, SubAssign};

/// A delegating `f64` that is wrong in method `WHICH` and correct everywhere else.
#[derive(Clone, Copy, PartialEq, Debug)]
pub(crate) struct Faulty<const WHICH: u32>(pub(crate) f64);

/// Perturb a value if its method is the selected one.
///
/// Three modes, keyed by the range `WHICH` falls in, because the three remaining mutants in
/// `conformance.rs` need three different kinds of wrongness:
///
/// | `WHICH` | Mode | What it is for |
/// |---|---|---|
/// | `k` | coarse: `−(1.5v + 0.25)` | the whole-body mutants: any law must notice |
/// | `1000 + k` | fine: `v·(1 + 1e-9)` | the *tolerance* mutants |
/// | `2000` | `trunc` becomes round-to-even | the `delete match arm` mutants |
///
/// # Why coarse is not enough
///
/// The bound in `real_laws` is `scale · tolerance`, and mutating that `*` to `+` makes it
/// `scale + tolerance` — about `1` instead of about `1e-12`. A coarse perturbation is rejected
/// under *either* bound (it mostly produces `NaN`, and `NaN ≤ anything` is false), so it cannot
/// tell the two apart. The fine mode is wrong by `1e-9` relative: comfortably over `1e-12` and
/// nowhere near `1`, so it is accepted exactly when the bound has been loosened.
///
/// # Why the sign flip is in the coarse mode
///
/// An affine perturbation of `floor` leaves it **idempotent** — with `v ↦ 1.5v + 0.25` the
/// broken `floor`'s image is `(0.25, 1.75)` and it maps that set to itself — and idempotence is
/// the only law `real_laws` states about `floor`. The first attempt at this carrier passed for
/// that reason, and the conclusion was not to loosen the test but that the perturbation sat in
/// the law's kernel.
fn perturb<const WHICH: u32>(identifier: u32, value: f64) -> f64 {
    const FINE: u32 = 1000;
    const LAWFUL_UNUSUAL: u32 = 2000;
    const TRUNC: u32 = 81;

    if WHICH == LAWFUL_UNUSUAL {
        // Lawful, and unusual. `trunc` rounds down to an even integer, which is idempotent — so
        // every law `real_laws` states still holds — while `trunc(floor(x)) ≠ floor(x)` for an
        // odd `floor(x)`. That is the one carrier the `delete match arm` mutants can be seen
        // with: the real suite accepts it and the mutated suite, which checks
        // `trunc(floor(x)) == floor(x)`, does not.
        if identifier == TRUNC {
            return 2.0 * (value / 2.0).floor();
        }
        return value;
    }
    if WHICH == identifier {
        return -(value * 1.5 + 0.25);
    }
    if WHICH == FINE + identifier {
        // Wrong by far more than the tolerance and far less than one.
        return value * (1.0 + 1e-9);
    }
    value
}

/// Flip a mask if its method is the selected one.
fn perturb_mask<const WHICH: u32>(identifier: u32, value: bool) -> bool {
    if WHICH == identifier { !value } else { value }
}

