//
// `Real: NormedDivisionAlgebra<RealPart = Self> + Compare`, and
// `NormedDivisionAlgebra: Arithmetic: Ring + Div`. The `Ring` tier and everything under it is
// blanket-implemented in `euclid-algebra` from marker traits, so a carrier needs the operators,
// the two identity constants, and the markers themselves — no law bodies.

// Explicit paths: `euclid-matrix/tests/residual.rs` pulls this file in with its own `#[path]`,
// which makes child modules resolve beside *it* rather than under `carrier/`. Naming the paths
// keeps one spelling that works from both the owning crate and the borrowing one.
#[path = "carrier/ops.rs"]
mod ops;
#[path = "carrier/real.rs"]
mod real;
